"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type RevealPrimitiveProps = ComponentProps<typeof motion.div>;

export function RevealPrimitive({ children, ...props }: RevealPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {opacity: 0,y: 20,clipPath: "inset(0 0 100% 0)"}}
      animate={{opacity: 1,y: 0,clipPath: "inset(0 0 0% 0)"}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 0.26, ease: [0.23, 1, 0.32, 1] }}

    >
      {children}
    </motion.div>
  );
}
